+
+/**
+ * Manages password access in memory and the local password database.
+ */
+class MsgPasswordAuthModule : public msgIPasswordAuthModule {
+ public:
+  NS_DECL_ISUPPORTS;
+  NS_DECL_MSGIPASSWORDAUTHMODULE;
