+
+ protected:
+  virtual ~MsgPasswordAuthModule() = default;
+
+ private:
+  nsString mPassword;
+};
+
+#endif  // COMM_MAILNEWS_BASE_SRC_MSGPASSWORDAUTHMODULE_H_
